import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import path from 'path'

// https://vite.dev/config/
export default defineConfig({
  plugins: [
    tailwindcss(),
    react(),
  ],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, './src'),
    },
  },
})

{
  "compilerOptions": {
    "tsBuildInfoFile": "./node_modules/.tmp/tsconfig.app.tsbuildinfo",
    "target": "es2023",
    "lib": ["ES2023", "DOM"],
    "module": "esnext",
    "types": ["vite/client"],
    "skipLibCheck": true,

    /* Bundler mode */
    "moduleResolution": "bundler",
    "allowImportingTsExtensions": true,
    "verbatimModuleSyntax": true,
    "moduleDetection": "force",
    "noEmit": true,
    "jsx": "react-jsx",

    /* Strict */
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "noImplicitOverride": true,
    "exactOptionalPropertyTypes": true,

    /* Linting */
    "noUnusedLocals": true,
    "noUnusedParameters": true,
    "erasableSyntaxOnly": true,
    "noFallthroughCasesInSwitch": true,

    /* Path aliases */
    "baseUrl": ".",
    "paths": {
      "@/*": ["src/*"]
    }
  },
  "include": ["src"]
}

@import "tailwindcss";

@theme {
  /* === Colors — placeholder tokens; token agent fills later === */
  --color-brand-50: #fdf4ff;
  --color-brand-100: #fae8ff;
  --color-brand-200: #f5d0fe;
  --color-brand-300: #f0abfc;
  --color-brand-400: #e879f9;
  --color-brand-500: #d946ef;
  --color-brand-600: #c026d3;
  --color-brand-700: #a21caf;
  --color-brand-800: #86198f;
  --color-brand-900: #701a75;

  --color-neutral-50: #fafafa;
  --color-neutral-100: #f5f5f5;
  --color-neutral-200: #e5e5e5;
  --color-neutral-300: #d4d4d4;
  --color-neutral-400: #a3a3a3;
  --color-neutral-500: #737373;
  --color-neutral-600: #525252;
  --color-neutral-700: #404040;
  --color-neutral-800: #262626;
  --color-neutral-900: #171717;
  --color-neutral-950: #0a0a0a;

  /* === Typography === */
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, "Cascadia Code", "Source Code Pro", Menlo, monospace;

  /* === Spacing scale (placeholder) === */
  --spacing-px: 1px;
  --spacing-0: 0px;
  --spacing-1: 0.25rem;
  --spacing-2: 0.5rem;
  --spacing-3: 0.75rem;
  --spacing-4: 1rem;
  --spacing-5: 1.25rem;
  --spacing-6: 1.5rem;
  --spacing-8: 2rem;
  --spacing-10: 2.5rem;
  --spacing-12: 3rem;
  --spacing-16: 4rem;
  --spacing-20: 5rem;
  --spacing-24: 6rem;
  --spacing-32: 8rem;

  /* === Radius === */
  --radius-sm: 0.25rem;
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;
  --radius-xl: 0.75rem;
  --radius-2xl: 1rem;
  --radius-full: 9999px;

  /* === shadcn-compat semantic tokens === */
  --color-background: var(--color-neutral-50);
  --color-foreground: var(--color-neutral-950);
  --color-muted: var(--color-neutral-100);
  --color-muted-foreground: var(--color-neutral-500);
  --color-border: var(--color-neutral-200);
  --color-input: var(--color-neutral-200);
  --color-ring: var(--color-brand-500);
  --color-primary: var(--color-brand-600);
  --color-primary-foreground: #ffffff;
  --color-secondary: var(--color-neutral-100);
  --color-secondary-foreground: var(--color-neutral-900);
  --color-accent: var(--color-brand-50);
  --color-accent-foreground: var(--color-brand-900);
  --color-destructive: #ef4444;
  --color-destructive-foreground: #ffffff;
  --color-card: #ffffff;
  --color-card-foreground: var(--color-neutral-950);
  --color-popover: #ffffff;
  --color-popover-foreground: var(--color-neutral-950);
}

/* Base resets */
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

export default function Variant1Spec() {
  return <div>Variant 1 Spec</div>;
}

export default function Variant2Spec() {
  return <div>Variant 2 Spec</div>;
}

export default function Variant3Spec() {
  return <div>Variant 3 Spec</div>;
}

export default function Variant4Spec() {
  return <div>Variant 4 Spec</div>;
}

export default function Variant5Spec() {
  return <div>Variant 5 Spec</div>;
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

// Design token references — token agent populates in Phase 4
// These map to the CSS custom properties defined in src/index.css @theme block

export const tokens = {
  colors: {
    brand: {
      50: 'var(--color-brand-50)',
      500: 'var(--color-brand-500)',
      600: 'var(--color-brand-600)',
    },
  },
} as const;

// Shared types — merch + elio agents extend in Phase 4

export interface Product {
  id: string;
  title: string;
  price: number;
  compareAtPrice?: number;
  images: string[];
  variants: ProductVariant[];
  description: string;
  tags: string[];
}

export interface ProductVariant {
  id: string;
  title: string;
  price: number;
  available: boolean;
  options: Record<string, string>;
}

import { Link } from 'react-router-dom';

const variants = [
  { label: 'Variant 1', path: '/variant-1' },
  { label: 'Variant 2', path: '/variant-2' },
  { label: 'Variant 3', path: '/variant-3' },
  { label: 'Variant 4', path: '/variant-4' },
  { label: 'Variant 5', path: '/variant-5' },
];

export default function Index() {
  return (
    <main className="min-h-screen bg-background text-foreground flex flex-col items-center justify-center gap-8 p-8">
      <h1 className="text-3xl font-semibold tracking-tight">Ecom Design Gallery</h1>
      <p className="text-muted-foreground text-sm">Select a variant to preview</p>
      <nav className="flex flex-col gap-3 w-full max-w-xs">
        {variants.map((v) => (
          <Link
            key={v.path}
            to={v.path}
            className="flex items-center justify-between rounded-lg border border-border bg-card px-4 py-3 text-sm font-medium hover:bg-muted transition-colors"
          >
            {v.label}
            <span className="text-muted-foreground">→</span>
          </Link>
        ))}
      </nav>
    </main>
  );
}

import { createBrowserRouter, RouterProvider } from 'react-router-dom';
import Index from '@/pages/Index';
import Variant1Spec from '@/variants/Variant1';
import Variant2Spec from '@/variants/Variant2';
import Variant3Spec from '@/variants/Variant3';
import Variant4Spec from '@/variants/Variant4';
import Variant5Spec from '@/variants/Variant5';

const router = createBrowserRouter([
  {
    path: '/',
    element: <Index />,
  },
  {
    path: '/variant-1',
    element: <Variant1Spec />,
  },
  {
    path: '/variant-2',
    element: <Variant2Spec />,
  },
  {
    path: '/variant-3',
    element: <Variant3Spec />,
  },
  {
    path: '/variant-4',
    element: <Variant4Spec />,
  },
  {
    path: '/variant-5',
    element: <Variant5Spec />,
  },
]);

export default function App() {
  return <RouterProvider router={router} />;
}
